from typing import Annotated, Literal, Union
from pydantic import BaseModel, Discriminator, Tag

class ApplePie(BaseModel):
    fruit: Literal['apple'] = 'apple'
    time_to_cook: int

class PumpkinPie(BaseModel):
    filling: Literal['pumpkin'] = 'pumpkin'
    time_to_cook: int

def get_kind(value):
    if isinstance(value, dict):
        return value.get('fruit', value.get('filling'))
    return getattr(value, 'fruit', getattr(value, 'filling', None))

class Dinner(BaseModel):
    dessert: Annotated[
        Annotated[ApplePie, Tag('apple')] | Annotated[PumpkinPie, Tag('pumpkin')],
        Discriminator(get_kind),
    ]

print(Dinner.model_validate({'dessert': {'fruit': 'apple', 'time_to_cook': 60}}))

